import Foundation
import Vapor
import NIO

// MARK: - File Processing Service for Kubernetes Pod
// Handles document conversion requests in a shared-nothing architecture

struct ConversionRequest: Content {
    let documentId: String
    let format: String
    let callbackURL: String?
}

struct ConversionResponse: Content {
    let status: String
    let outputPath: String?
    let error: String?
}

// Security: Validates document IDs to prevent path traversal
func validateDocumentId(_ id: String) -> Bool {
    let allowedChars = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "-_"))
    return id.unicodeScalars.allSatisfy { allowedChars.contains($0) } && id.count <= 64
}

// MARK: - Temp File Manager with Pod-Aware Cleanup
class SecureTempFileManager {
    private let baseDir: String
    private let podName: String
    private let namespace: String
    private let fileManager = FileManager.default

    init() {
        self.podName = ProcessInfo.processInfo.environment["POD_NAME"] ?? "unknown"
        self.namespace = ProcessInfo.processInfo.environment["K8S_NAMESPACE"] ?? "default"
        // Use emptyDir volume mount for temp files in k8s
        self.baseDir = ProcessInfo.processInfo.environment["TEMP_VOLUME_PATH"] ?? "/tmp/converter"
    }

    /// Creates a working directory for a conversion task
    /// Returns the path to the secure temporary directory
    func createWorkingDirectory(for taskId: String) throws -> String {
        let sanitizedTask = taskId.replacingOccurrences(of: "..", with: "")
                                   .replacingOccurrences(of: "/", with: "")

        // Construct path with pod identity for multi-tenant isolation
        let dirName = "\(namespace)_\(podName)_\(sanitizedTask)"
        let workDir = "\(baseDir)/\(dirName)"

        try fileManager.createDirectory(
            atPath: workDir,
            withIntermediateDirectories: true,
            attributes: [.posixPermissions: 0o700]
        )

        return workDir
    }

    /// Creates a temporary file within the working directory
    /// Uses atomic write pattern for crash safety
    func createTempFile(in directory: String, prefix: String, content: Data) throws -> String {
        let uniqueComponent = ProcessInfo.processInfo.globallyUniqueString
        let fileName = "\(prefix)_\(uniqueComponent)"
        let filePath = "\(directory)/\(fileName)"

        // Write to staging location first, then move atomically
        let stagingPath = NSTemporaryDirectory() + fileName + ".staging"

        guard fileManager.createFile(atPath: stagingPath, contents: content, attributes: [
            .posixPermissions: 0o600
        ]) else {
            throw Abort(.internalServerError, reason: "Failed to create staging file")
        }

        try fileManager.moveItem(atPath: stagingPath, toPath: filePath)
        return filePath
    }

    /// Cleanup with race-condition-safe deletion
    func cleanupWorkingDirectory(_ path: String) throws {
        // Verify the path is under our base directory before deletion
        let resolvedBase = (baseDir as NSString).resolvingSymlinksInPath
        let resolvedPath = (path as NSString).resolvingSymlinksInPath

        guard resolvedPath.hasPrefix(resolvedBase) else {
            throw Abort(.forbidden, reason: "Attempted cleanup outside base directory")
        }

        try fileManager.removeItem(atPath: path)
    }
}

// MARK: - Conversion Pipeline
class DocumentConverter {
    private let tempManager = SecureTempFileManager()
    private let supportedFormats = ["pdf", "docx", "html", "txt"]

    func convert(request: ConversionRequest) async throws -> ConversionResponse {
        guard validateDocumentId(request.documentId) else {
            return ConversionResponse(status: "error", outputPath: nil, error: "Invalid document ID")
        }

        guard supportedFormats.contains(request.format.lowercased()) else {
            return ConversionResponse(status: "error", outputPath: nil, error: "Unsupported format")
        }

        let taskId = UUID().uuidString
        let workDir = try tempManager.createWorkingDirectory(for: taskId)

        defer {
            try? tempManager.cleanupWorkingDirectory(workDir)
        }

        // Simulate fetching document from object storage
        let documentData = try await fetchDocument(id: request.documentId)

        // Create input temp file
        let inputPath = try tempManager.createTempFile(
            in: workDir,
            prefix: "input",
            content: documentData
        )

        // Perform conversion (calls external tool)
        let outputPath = try await performConversion(
            inputPath: inputPath,
            format: request.format,
            workDir: workDir
        )

        return ConversionResponse(status: "completed", outputPath: outputPath, error: nil)
    }

    private func fetchDocument(id: String) async throws -> Data {
        // In production: fetch from S3/GCS using service account
        return Data("sample document content".utf8)
    }

    private func performConversion(inputPath: String, format: String, workDir: String) async throws -> String {
        let outputFile = "\(workDir)/output.\(format)"

        // Shell out to conversion tool with restricted PATH
        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/usr/local/bin/docconvert")
        process.arguments = ["--input", inputPath, "--output", outputFile, "--format", format]
        process.environment = [
            "PATH": "/usr/local/bin:/usr/bin",
            "HOME": workDir,
            "TMPDIR": workDir
        ]

        // Set resource limits via cgroup awareness
        process.currentDirectoryURL = URL(fileURLWithPath: workDir)

        try process.run()
        process.waitUntilExit()

        guard process.terminationStatus == 0 else {
            throw Abort(.internalServerError, reason: "Conversion failed with status \(process.terminationStatus)")
        }

        return outputFile
    }
}

// MARK: - Route Configuration
func routes(_ app: Application) throws {
    let converter = DocumentConverter()

    app.post("convert") { req async throws -> ConversionResponse in
        let request = try req.content.decode(ConversionRequest.self)
        return try await converter.convert(request: request)
    }

    // Health check for k8s liveness probe
    app.get("healthz") { req -> HTTPStatus in
        return .ok
    }
}
